trial.program_source:
def transform(grid):
 out=[r[:] for r in grid]
 colors=sorted({v for row in grid for v in row if v},reverse=True)
 for v in colors:
  pts={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==v}
  col=next(iter(pts))[1]
  for r in range(min(r for r,c in pts),max(r for r,c in pts)+1): out[r][col]=v
  for r,c in pts:
   for j in range(min(c,col),max(c,col)+1): out[r][j]=v
 return out

